"""Deutsch — Sira (sira_001 … sira_150)."""

T = {
"sira_001": ("In welcher Stadt wurde der Prophet Muhammad ﷺ geboren?", ["Mekka", "Medina", "Ta'if", "Jerusalem"], "Der Prophet Muhammad ﷺ wurde in Mekka, im Hidschas, geboren."),
"sira_002": ("Wie heißt das Geburtsjahr des Propheten ﷺ, geprägt vom Ereignis des Elefanten?", ["Das Jahr des Elefanten", "Das Jahr des Sieges", "Das Jahr des Kamels", "Das Jahr des Lichts"], "Das Ereignis des Elefanten, bei dem Allah die Ka'ba schützte, wird in der Sure Al-Fil erzählt."),
"sira_003": ("Wie hieß die erste Frau des Propheten ﷺ?", ["Khadija", "Aisha", "Hafsa", "Zaynab"], "Khadija bint Khuwaylid war die erste Frau des Propheten ﷺ und der erste Mensch, der an seine Botschaft glaubte."),
"sira_004": ("In welcher Höhle empfing der Prophet ﷺ die erste Offenbarung?", ["In der Höhle Hira", "In der Höhle Thawr", "In der Höhle der Gefährten", "In der Höhle Uhud"], "Die erste Offenbarung fand in der Höhle Hira auf dem Jabal an-Nur bei Mekka statt."),
"sira_005": ("Welcher Engel brachte dem Propheten ﷺ die Offenbarung?", ["Jibril (Gabriel)", "Mika'il (Michael)", "Israfil", "Malik"], "Der Koran erwähnt ausdrücklich, dass Jibril die Offenbarung mit Allahs Erlaubnis brachte."),
"sira_006": ("Wie heißt die Auswanderung des Propheten ﷺ und seiner Gefährten von Mekka nach Medina?", ["Die Hidschra", "Al-Isra", "Al-Mi'raj", "Al-Fath"], "Die Hidschra ist die historische Auswanderung nach Medina, der Ausgangspunkt des islamischen Kalenders."),
"sira_007": ("In welche Stadt wanderten der Prophet ﷺ und Abu Bakr aus?", ["Medina", "Ta'if", "Damaskus", "Jerusalem"], "Der Prophet ﷺ und Abu Bakr wanderten von Mekka nach Medina (damals Yathrib genannt) aus."),
"sira_008": ("Der Koran beschreibt einen Gefährten als „den zweiten von zweien, als sie in der Höhle waren“ während der Hidschra. Wer war es?", ["Abu Bakr", "Umar", "Uthman", "Ali"], "Der Koran meint Abu Bakr, der den Propheten ﷺ während der Hidschra in der Höhle Thawr begleitete."),
"sira_009": ("In welcher im Koran erwähnten Schlacht besiegte ein kleines muslimisches Heer eine weit größere Streitmacht?", ["Die Schlacht von Badr", "Die Schlacht von Uhud", "Die Grabenschlacht", "Die Schlacht von Hunayn"], "Bei Badr schenkte Allah einer kleinen Gruppe Gläubiger den Sieg über ein weit größeres Heer."),
"sira_010": ("Wie heißt die weitgehend friedliche Rückkehr des Propheten ﷺ und seiner Gefährten nach Mekka?", ["Die Eroberung Mekkas (Fath Makka)", "Die Schlacht um Mekka", "Die Belagerung Mekkas", "Der Fall Mekkas"], "Die Eroberung Mekkas verlief weitgehend friedlich, ohne großes Blutvergießen."),
"sira_011": ("Wie heißt die letzte Predigt, die der Prophet ﷺ gegen Ende seines Lebens hielt?", ["Die Abschiedspredigt", "Die Predigt von Mekka", "Die Höhlenpredigt", "Die Predigt von Badr"], "Die Abschiedspredigt (Khutbat al-Wada') wurde während der letzten Pilgerfahrt des Propheten ﷺ gehalten."),
"sira_012": ("In welchem Monat begann laut Koran seine Offenbarung?", ["Ramadan", "Muharram", "Rajab", "Dhul-Hijja"], "Der Koran sagt, dass der Ramadan der Monat ist, in dem der Koran herabgesandt wurde."),
"sira_013": ("Welchen Beruf übte der Prophet ﷺ vor der Offenbarung aus?", ["Kaufmann", "Nur Hirte", "Schmied", "Schreiber"], "Der Prophet ﷺ war im Handel tätig, eine gesicherte Tatsache seiner Biografie."),
"sira_014": ("Welcher Großvater des Propheten ﷺ sorgte nach dem Tod seiner Mutter für ihn?", ["Abdul Muttalib", "Abu Talib", "Abu Lahab", "Abu Sufyan"], "Abdul Muttalib sorgte nach dem Tod seiner Mutter Amina für den jungen Muhammad ﷺ."),
"sira_015": ("Welcher Onkel zog den Propheten ﷺ nach dem Tod seines Großvaters auf?", ["Abu Talib", "Al-Abbas", "Hamza", "Abu Lahab"], "Abu Talib übernahm nach dem Tod Abdul Muttalibs die Erziehung seines Neffen."),
"sira_016": ("Wie heißt die im Koran erwähnte Nachtreise des Propheten ﷺ von Mekka nach Jerusalem?", ["Al-Isra", "Die Hidschra", "Al-Fath", "Al-Ghazwa"], "Die Sure Al-Isra beginnt mit der Beschreibung dieser wunderbaren Nachtreise."),
"sira_017": ("Welche Tochter des Propheten ﷺ heiratete Ali ibn Abi Talib?", ["Fatima", "Zaynab", "Ruqayya", "Umm Kulthum"], "Fatima, Tochter des Propheten ﷺ und Khadijas, heiratete Ali ibn Abi Talib, eine allgemein gesicherte Tatsache."),
"sira_018": ("Welcher Monat markiert den Jahresbeginn des islamischen Kalenders, mit Bezug auf die Hidschra?", ["Muharram", "Ramadan", "Shawwal", "Dhul-Qa'da"], "Der islamische Kalender beginnt mit dem Monat Muharram und nimmt das Jahr der Hidschra als Bezugspunkt."),
"sira_019": ("Wer war der erste Muezzin des Islam, vom Propheten ﷺ zum Gebetsruf auserwählt?", ["Bilal ibn Rabah", "Abu Bakr", "Umar ibn al-Khattab", "Salman al-Farisi"], "Bilal wurde mit seiner schönen Stimme zum ersten Muezzin des Islam gewählt."),
"sira_020": ("Welche Moschee gründete der Prophet ﷺ als erste, als er in der Nähe von Medina ankam?", ["Die Moschee von Quba", "Die Al-Haram-Moschee", "Die Al-Aqsa-Moschee", "Die Moschee der zwei Gebetsrichtungen"], "Bei seiner Ankunft in Quba, vor den Toren Medinas, gründete der Prophet ﷺ dort die erste Moschee."),
"sira_021": ("Wie hieß die Mutter des Propheten ﷺ?", ["Amina", "Khadija", "Halima", "Fatima"], "Amina bint Wahb war die Mutter des Propheten ﷺ; Halima war seine Amme."),
"sira_022": ("Wie hieß der Vater des Propheten ﷺ, der vor seiner Geburt starb?", ["Abdullah", "Abu Talib", "Abd al-Muttalib", "Hamza"], "Abdullah, Sohn Abd al-Muttalibs, starb, bevor sein Sohn Muhammad ﷺ geboren wurde."),
"sira_023": ("Welchen Beinamen gaben die Mekkaner dem Propheten ﷺ vor der Offenbarung wegen seiner Ehrlichkeit?", ["Al-Amin (der Vertrauenswürdige)", "Al-Faruq", "As-Siddiq", "Sayf Allah"], "Schon vor der Offenbarung nannte man ihn al-Amin: Die Leute vertrauten ihm ihr Hab und Gut an."),
"sira_024": ("In welchem Jahr der Hidschra fand die Eroberung Mekkas statt?", ["Im Jahr 8", "Im Jahr 2", "Im Jahr 5", "Im Jahr 10"], "Im Jahr 8 n. H. zog der Prophet ﷺ fast ohne Kampf in Mekka ein und vergab seinen Bewohnern."),
"sira_025": ("In welchem Jahr der Hidschra vollzog der Prophet ﷺ seine Abschiedspilgerfahrt?", ["Im Jahr 10", "Im Jahr 6", "Im Jahr 8", "Im Jahr 12"], "Die Abschiedspilgerfahrt fand im Jahr 10 n. H. statt; der Prophet ﷺ hielt dort seine letzte Predigt."),
"sira_026": ("Wie viele Töchter hatte der Prophet ﷺ?", ["4", "1", "2", "7"], "Zaynab, Ruqayya, Umm Kulthum und Fatima: die vier Töchter des Propheten ﷺ."),
"sira_027": ("Wie nennt man die Bewohner Medinas, die die ausgewanderten Muslime aufnahmen und ihnen halfen?", ["Die Ansar (die Helfer)", "Die Muhajirun", "Die Quraysh", "Die Tabi'un"], "Die Ansar, „die Helfer“, teilten ihre Häuser und ihren Besitz mit ihren ausgewanderten Brüdern."),
"sira_028": ("Wie nennt man die Muslime, die Mekka verließen, um nach Medina auszuwandern?", ["Die Muhajirun (die Auswanderer)", "Die Ansar", "Die Hunafa'", "Die Ghuzat"], "Die Muhajirun ließen Häuser und Besitz in Mekka zurück, um ihren Glauben zu bewahren."),
"sira_029": ("In welchem Monat fand die Schlacht von Badr statt?", ["Ramadan", "Muharram", "Dhul-Hijja", "Rajab"], "Die Schlacht von Badr fand im Ramadan des Jahres 2 n. H. statt."),
"sira_030": ("Zu welcher Stadt hin beteten die Muslime, bevor die Gebetsrichtung auf die Ka'ba festgelegt wurde?", ["Jerusalem (Bayt al-Maqdis)", "Medina", "Ta'if", "Damaskus"], "Die Muslime beteten zunächst nach Bayt al-Maqdis; dann befahl Allah, sich zur Heiligen Moschee zu wenden (Koran 2:142-144)."),
"sira_031": ("Welchem Stamm gehörte der Prophet Muhammad ﷺ an?", ["Quraysh", "Den Aws", "Den Khazraj", "Thaqif"], "Eine ganze Sure trägt den Namen seines Stammes: Quraysh."),
"sira_032": ("Aus welcher Sippe der Quraysh stammte der Prophet ﷺ?", ["Banu Hashim", "Banu Umayya", "Banu Makhzum", "Banu Tamim"], "Der Prophet ﷺ gehörte zu den Banu Hashim, der Sippe seines Urgroßvaters Hashim."),
"sira_033": ("Wie hieß die Amme, die den Propheten ﷺ in der Wüste stillte?", ["Halima as-Sa'diyya", "Amina", "Khadija", "Fatima"], "Nach mekkanischem Brauch wurde das Kind einer beduinischen Amme anvertraut: Halima as-Sa'diyya."),
"sira_034": ("Welcher Onkel des Propheten ﷺ, ein Held von Badr, fiel bei Uhud als Märtyrer?", ["Hamza", "Abu Talib", "Al-Abbas", "Abu Lahab"], "Hamza ibn Abd al-Muttalib kämpfte bei Badr und fiel in der Schlacht von Uhud."),
"sira_035": ("Welcher Cousin des Propheten ﷺ, in seinem Haus aufgewachsen, wurde der vierte Kalif?", ["Ali ibn Abi Talib", "Ja'far", "Aqil", "Al-Abbas"], "Ali, Sohn Abu Talibs, wuchs beim Propheten ﷺ auf und war der vierte rechtgeleitete Kalif."),
"sira_036": ("Wer war der erste Kalif nach dem Tod des Propheten ﷺ?", ["Abu Bakr", "Umar", "Uthman", "Ali"], "Abu Bakr as-Siddiq wurde zum ersten Kalifen gewählt."),
"sira_037": ("Welchen Titel trägt Abu Bakr, weil er dem Propheten ﷺ ohne Zögern glaubte?", ["As-Siddiq (der Wahrhaftige)", "Al-Faruq", "Dhun-Nurayn", "Sayf Allah"], "Abu Bakr wird as-Siddiq genannt, derjenige, der die Wahrheit bestätigt und ihr glaubt."),
"sira_038": ("Welchen Titel trägt Umar ibn al-Khattab?", ["Al-Faruq (der Wahrheit von Falschheit unterscheidet)", "As-Siddiq", "Dhun-Nurayn", "Al-Amin"], "Umar wird al-Faruq genannt, derjenige, der Wahrheit von Falschheit trennt."),
"sira_039": ("Warum wird Uthman ibn Affan „Dhun-Nurayn“, der Besitzer zweier Lichter, genannt?", ["Er heiratete nacheinander zwei Töchter des Propheten ﷺ", "Er trug zwei Lampen", "Er lernte den Koran zweimal auswendig", "Er machte zwei Hidschras"], "Uthman heiratete Ruqayya und nach ihrem Tod Umm Kulthum, beide Töchter des Propheten ﷺ."),
"sira_040": ("In welcher Reihenfolge folgten die vier rechtgeleiteten Kalifen aufeinander?", ["Abu Bakr, Umar, Uthman, Ali", "Ali, Umar, Abu Bakr, Uthman", "Umar, Abu Bakr, Ali, Uthman", "Abu Bakr, Ali, Umar, Uthman"], "Abu Bakr, dann Umar, dann Uthman, dann Ali."),
"sira_041": ("Wer war der erste Mensch, der an die Botschaft des Propheten ﷺ glaubte?", ["Khadija, seine Frau", "Abu Bakr", "Ali", "Bilal"], "Khadija glaubte ihm von der ersten Offenbarung an und unterstützte ihn."),
"sira_042": ("Wer kaufte Bilal frei, um ihn von den Folterungen seines Herrn zu befreien?", ["Abu Bakr", "Umar", "Hamza", "Uthman"], "Abu Bakr kaufte Bilal und ließ ihn frei."),
"sira_043": ("Wer war die erste Märtyrerin des Islam, in Mekka für ihren Glauben getötet?", ["Sumayya, Mutter Ammars", "Asma", "Umm Salama", "Safiyya"], "Sumayya bint Khayyat, Mutter von Ammar ibn Yasir, wurde von Abu Jahl getötet."),
"sira_044": ("In welches Land fand die erste Auswanderung der in Mekka verfolgten Muslime statt?", ["Abessinien (Äthiopien)", "Persien", "Jemen", "Ägypten"], "Die ersten Auswanderer gingen nach Abessinien, zu einem gerechten König."),
"sira_045": ("Wie hieß der König von Abessinien, der die Muslime beschützte und für den der Prophet ﷺ das Totengebet in Abwesenheit verrichtete?", ["An-Najashi (der Negus)", "Herakleios", "Chosrau", "Al-Muqawqis"], "Der Prophet ﷺ verkündete den Tod des Negus am selben Tag und betete mit den Gefährten für ihn."),
"sira_046": ("Welcher Gefährte sprach vor dem Negus, um den Islam zu erklären?", ["Ja'far ibn Abi Talib", "Uthman", "Bilal", "Mus'ab ibn Umayr"], "Ja'far erklärte dem König, was der Prophet ﷺ lehrte, und trug ihm Verse der Sure Maryam vor."),
"sira_047": ("Welcher Onkel des Propheten ﷺ wird im Koran namentlich verurteilt?", ["Abu Lahab", "Abu Talib", "Al-Abbas", "Hamza"], "„Zugrunde gehen sollen die Hände Abu Lahabs, und zugrunde gehen soll er!“"),
"sira_048": ("Wie heißt das Jahr, in dem der Prophet ﷺ seine Frau Khadija und seinen Onkel Abu Talib verlor?", ["Das Jahr der Trauer", "Das Jahr des Elefanten", "Das Jahr der Delegationen", "Das Jahr der Hungersnot"], "Die beiden großen Stützen des Propheten ﷺ starben im selben Jahr, das als Jahr der Trauer bekannt ist."),
"sira_049": ("In welcher Stadt wurde der Prophet ﷺ nach seinem Ruf zum Islam vertrieben und verletzt, bevor er ablehnte, dass der Engel der Berge ihre Bewohner zermalmte?", ["At-Ta'if", "Medina", "Khaybar", "Tabuk"], "In Ta'if abgewiesen, weigerte er sich, dessen Bewohner zu vernichten, in der Hoffnung, ihre Nachkommen würden Allah anbeten."),
"sira_050": ("Welche Pflicht wurde den Muslimen während der Nachtreise und Himmelfahrt (Isra und Mi'raj) vorgeschrieben?", ["Die fünf täglichen Gebete", "Das Fasten im Ramadan", "Die Zakat", "Die Pilgerfahrt"], "Die Gebete wurden in jener Nacht vorgeschrieben, von fünfzig auf fünf verringert, mit dem Lohn von fünfzig."),
"sira_051": ("Welchen Baum an der äußersten Grenze sah der Prophet ﷺ laut Sure An-Najm während der Himmelfahrt?", ["Sidrat al-Muntaha", "Den gesegneten Olivenbaum", "Die Palme Maryams", "Den Baum Tuba"], "„Bei Sidrat al-Muntaha“, dem Lotusbaum der äußersten Grenze."),
"sira_052": ("Wie heißen die Treueschwüre, die Bewohner Yathribs dem Propheten ﷺ vor der Hidschra leisteten?", ["Die Schwüre von Al-Aqaba", "Der Vertrag von Hudaybiyya", "Der Schwur unter dem Baum", "Die Verfassung von Medina"], "Bewohner Yathribs schworen dem Propheten ﷺ vor der Hidschra in Al-Aqaba bei Mina die Treue."),
"sira_053": ("Welchen Gefährten sandte der Prophet ﷺ vor der Hidschra nach Yathrib, um den Islam zu lehren?", ["Mus'ab ibn Umayr", "Bilal", "Abu Hurayra", "Khalid ibn al-Walid"], "Mus'ab ibn Umayr war der erste Gesandte nach Yathrib und lehrte die neuen Muslime den Koran."),
"sira_054": ("Wer schlief in der Nacht, als der Prophet ﷺ zur Hidschra aufbrach, in seinem Bett?", ["Ali ibn Abi Talib", "Abu Bakr", "Zayd ibn Haritha", "Bilal"], "Ali nahm seinen Platz im Bett ein, um die Wächter zu täuschen, und gab dann den Mekkanern ihre hinterlegten Güter zurück."),
"sira_055": ("In welcher Höhle versteckten sich der Prophet ﷺ und Abu Bakr während der Hidschra?", ["In der Höhle Thawr", "In der Höhle Hira", "In der Höhle Uhud", "In der Höhle Ta'if"], "Sie versteckten sich drei Tage in der Höhle Thawr, südlich von Mekka."),
"sira_056": ("Welche Tochter Abu Bakrs brachte Vorräte zur Höhle und erhielt den Beinamen „die mit den zwei Gürteln“?", ["Asma", "Aisha", "Umm Kulthum", "Umm Ruman"], "Asma zerriss ihren Gürtel in zwei Teile, um die Vorräte festzubinden: daher „Dhat an-Nitaqayn“."),
"sira_057": ("Was geschah Suraqa, der den Propheten ﷺ während der Hidschra verfolgte?", ["Sein Pferd sank in den Boden ein, und er bat um Sicherheit", "Er holte den Propheten ﷺ ein", "Er verirrte sich in der Wüste", "Er wurde krank"], "Die Beine seines Pferdes sanken in die Erde; Suraqa bat um freies Geleit und zog ohne Schaden ab."),
"sira_058": ("Wie lautete der alte, im Koran erwähnte Name Medinas?", ["Yathrib", "Tayba", "Khaybar", "Bakka"], "„O Leute von Yathrib…“, sagt der Koran und erinnert an die Schlacht der Verbündeten."),
"sira_059": ("Wie hieß die Kamelstute des Propheten ﷺ, die sich bei Hudaybiyya niederkniete?", ["Al-Qaswa", "Al-Buraq", "Ad-Duldul", "Al-Adba"], "Bei Hudaybiyya kniete Al-Qaswa nieder; der Prophet ﷺ sagte: „Der den Elefanten zurückhielt, hat sie zurückgehalten.“"),
"sira_060": ("Was stiftete der Prophet ﷺ bei seiner Ankunft in Medina zwischen den Muhajirun und den Ansar?", ["Eine Bruderschaft, paarweise", "Eine Steuer", "Ein Heer", "Einen Markt"], "Er verbrüderte die Auswanderer mit den Helfern, jeden Muhajir mit einem Bruder aus den Ansar."),
"sira_061": ("Wie heißt das Dokument, mit dem der Prophet ﷺ die Beziehungen zwischen den Gemeinschaften Medinas ordnete?", ["Die Sahifa (Verfassung) von Medina", "Der Vertrag von Hudaybiyya", "Der Pakt von Ta'if", "Die Charta von Quba"], "Die Sahifa legte die Rechte und Pflichten der Muslime und der anderen Stämme Medinas fest."),
"sira_062": ("Wie nannte man die armen Gefährten, die in der Moschee des Propheten ﷺ lebten?", ["Ahl as-Suffa (die Leute der Bank)", "Die Muhajirun", "Die Ansar", "Die Hawariyyun"], "Abu Hurayra berichtet, dass er zu den Leuten der Suffa gehörte, die vom Propheten ﷺ verpflegt wurden."),
"sira_063": ("Wie viele Jahre nach der Hidschra fand die Schlacht von Badr statt?", ["Zwei", "Fünf", "Acht", "Zehn"], "Badr wurde im Jahr 2 n. H. während des Ramadan geschlagen."),
"sira_064": ("Wie viele Engel versprach Allah den Gläubigen bei Badr als Verstärkung zu senden?", ["Tausend", "Hundert", "Zehn", "Hunderttausend"], "„Ich werde euch mit tausend Engeln verstärken, die aufeinander folgen.“"),
"sira_065": ("Welcher Fehler der Bogenschützen wendete bei Uhud die Schlacht?", ["Sie verließen den Hügel trotz des Befehls des Propheten ﷺ", "Sie schossen zu früh", "Sie schliefen ein", "Sie wechselten die Seite"], "Der Prophet ﷺ hatte den Bogenschützen befohlen, sich nicht zu bewegen; die meisten stiegen wegen der Beute hinab, und die feindliche Reiterei umging sie."),
"sira_066": ("In der Nähe welcher Stadt liegt der Berg Uhud?", ["Medina", "Mekka", "Ta'if", "Jerusalem"], "Der Berg Uhud liegt nördlich von Medina; die Schlacht fand an seinem Fuß statt."),
"sira_067": ("Welcher Gefährte schlug vor, einen Graben zur Verteidigung Medinas gegen die Verbündeten auszuheben?", ["Salman al-Farisi", "Bilal", "Abu Dharr", "Suhayb"], "Salman der Perser schlug den Graben vor, eine in Persien bekannte Taktik."),
"sira_068": ("Unter welchem anderen Namen ist die Grabenschlacht bekannt, nach der Sure, die von ihr spricht?", ["Die Schlacht der Verbündeten (Al-Ahzab)", "Die Schlacht von Badr", "Die Schlacht von Hunayn", "Die Schlacht von Mu'ta"], "Die Sure Al-Ahzab erinnert an die verbündeten Heere, die Medina belagerten, und den Wind, der gegen sie gesandt wurde."),
"sira_069": ("Wie heißt der Schwur unter einem Baum bei Hudaybiyya, mit dem Allah, wie Er sagt, zufrieden war?", ["Bay'at ar-Ridwan", "Bay'at al-Aqaba", "Bay'at an-Nisa", "Bay'at al-Fath"], "„Allah hatte Wohlgefallen an den Gläubigen, als sie dir unter dem Baum die Treue schworen.“"),
"sira_070": ("Welche Sure beginnt mit „Wir haben dir einen klaren Sieg geschenkt“, offenbart nach dem Vertrag von Hudaybiyya?", ["Al-Fath", "An-Nasr", "Al-Anfal", "At-Tawba"], "„Wahrlich, Wir haben dir einen klaren Sieg geschenkt“: die Sure Al-Fath."),
"sira_071": ("In welchem Jahr der Hidschra wurde der Vertrag von Hudaybiyya geschlossen?", ["Im Jahr 6", "Im Jahr 2", "Im Jahr 8", "Im Jahr 10"], "Der Vertrag von Hudaybiyya wurde im Jahr 6 n. H. zwischen den Muslimen und den Quraysh geschlossen."),
"sira_072": ("Welcher byzantinische Kaiser erhielt den Brief des Propheten ﷺ mit der Einladung zum Islam und befragte Abu Sufyan über ihn?", ["Herakleios", "Nero", "Konstantin", "Justinian"], "Herakleios befragte Abu Sufyan über den Propheten ﷺ, nachdem er seinen Brief erhalten hatte."),
"sira_073": ("Wem übergab der Prophet ﷺ bei Khaybar das Banner, nachdem er gesagt hatte: „Morgen gebe ich es einem Mann, den Allah und Sein Gesandter lieben“?", ["Ali ibn Abi Talib", "Abu Bakr", "Umar", "Sa'd ibn Abi Waqqas"], "Er rief Ali, der an den Augen litt; er bestrich sie mit seinem Speichel, heilte ihn und gab ihm das Banner."),
"sira_074": ("Welche drei Befehlshaber fielen nacheinander in der Schlacht von Mu'ta?", ["Zayd ibn Haritha, Ja'far ibn Abi Talib und Abdullah ibn Rawaha", "Hamza, Mus'ab und Sa'd", "Abu Bakr, Umar und Uthman", "Bilal, Salman und Suhayb"], "Der Prophet ﷺ verkündete in Medina: „Zayd nahm das Banner und fiel, dann Ja'far, dann Ibn Rawaha… dann nahm es ein Schwert Allahs.“"),
"sira_075": ("Welchen Gefährten nannte der Prophet ﷺ „ein Schwert unter den Schwertern Allahs“?", ["Khalid ibn al-Walid", "Ali", "Hamza", "Abu Ubayda"], "Bei Mu'ta nahm „ein Schwert unter den Schwertern Allahs“, Khalid ibn al-Walid, das Banner und rettete das Heer."),
"sira_076": ("Was tat der Prophet ﷺ bei der Eroberung Mekkas mit den Götzen rund um die Ka'ba?", ["Er stürzte sie um und trug vor: „Die Wahrheit ist gekommen, und das Falsche ist vergangen“", "Er verkaufte sie", "Er brachte sie nach Medina", "Er ließ sie stehen"], "Er stieß die Götzen mit seinem Stock um und sagte: „Die Wahrheit ist gekommen, und das Falsche ist vergangen.“"),
"sira_077": ("Wer rief am Tag der Eroberung Mekkas vom Dach der Ka'ba zum Gebet?", ["Bilal", "Abu Bakr", "Ali", "Umar"], "Der Prophet ﷺ befahl Bilal, auf die Ka'ba zu steigen und zum Gebet zu rufen."),
"sira_078": ("Was sagte der Prophet ﷺ am Tag der Eroberung zu den besiegten Mekkanern, die ihn verfolgt hatten?", ["„Geht, ihr seid frei“", "„Ihr werdet morgen gerichtet“", "„Verlasst die Stadt“", "„Zahlt ein Lösegeld“"], "Er vergab ihnen: „Geht, ihr seid frei.“"),
"sira_079": ("In welcher im Koran genannten Schlacht wurden die Muslime trotz ihrer großen Zahl zunächst überrascht?", ["Hunayn", "Badr", "Uhud", "Khaybar"], "„Am Tag von Hunayn gefiel euch eure große Zahl, doch sie nützte euch nichts.“"),
"sira_080": ("Welcher Gefährte, der dem Feldzug nach Tabuk fernblieb, gestand ehrlich und wurde durch eine Offenbarung begnadigt?", ["Ka'b ibn Malik", "Abu Dharr", "Anas ibn Malik", "Abu Hurayra"], "Ka'b ibn Malik sagte die Wahrheit, ertrug fünfzig Tage der Ausgrenzung, dann offenbarte Allah seine Vergebung (9:118)."),
"sira_081": ("Wie heißt das Jahr 9 n. H., in dem viele Stämme nach Medina kamen, um den Islam anzunehmen?", ["Das Jahr der Delegationen", "Das Jahr der Trauer", "Das Jahr des Elefanten", "Das Jahr der Dürre"], "Nach der Eroberung Mekkas strömten Delegationen arabischer Stämme nach Medina."),
"sira_082": ("Wo hielt der Prophet ﷺ seine Abschiedspredigt?", ["In Arafat", "In Medina", "Auf dem Berg Uhud", "In Ta'if"], "Die Abschiedspredigt wurde in Arafat während der Abschiedspilgerfahrt gehalten."),
"sira_083": ("Welcher während der Abschiedspilgerfahrt offenbarte Vers verkündet, dass die Religion vollendet ist?", ["„Heute habe Ich euch eure Religion vervollkommnet“", "„Lies, im Namen deines Herrn“", "„Wenn Allahs Hilfe kommt“", "„Sprich: Er ist Allah, ein Einziger“"], "„Heute habe Ich euch eure Religion vervollkommnet und Meine Gnade an euch vollendet.“"),
"sira_084": ("In welcher Stadt starb der Prophet ﷺ und wurde begraben?", ["Medina", "Mekka", "Jerusalem", "Ta'if"], "Er starb im Jahr 11 n. H. in Medina und wurde dort begraben."),
"sira_085": ("Im Zimmer welcher Ehefrau wurde der Prophet ﷺ begraben?", ["Aishas", "Khadijas", "Hafsas", "Umm Salamas"], "Er wurde dort begraben, wo er starb, in Aishas Zimmer, heute innerhalb der Prophetenmoschee."),
"sira_086": ("Wer erklärte beim Tod des Propheten ﷺ: „Wer Muhammad anbetete, Muhammad ist gestorben; wer Allah anbetet, Allah ist der Lebendige“?", ["Abu Bakr", "Umar", "Ali", "Bilal"], "Abu Bakr beruhigte die Gefährten und trug vor: „Muhammad ist nur ein Gesandter…“ (3:144)."),
"sira_087": ("Wie hießen die beiden Enkel des Propheten ﷺ, die Söhne Fatimas und Alis?", ["Al-Hasan und Al-Husayn", "Ibrahim und Isma'il", "Zayd und Usama", "Ja'far und Aqil"], "Al-Hasan und Al-Husayn, die der Prophet ﷺ innig liebte."),
"sira_088": ("Welche Ehefrau des Propheten ﷺ war die Tochter Abu Bakrs?", ["Aisha", "Hafsa", "Zaynab", "Sawda"], "Aisha, Tochter Abu Bakrs, überlieferte eine sehr große Zahl von Hadithen."),
"sira_089": ("Welche Ehefrau des Propheten ﷺ war die Tochter Umar ibn al-Khattabs?", ["Hafsa", "Aisha", "Umm Habiba", "Maymuna"], "Hafsa bint Umar; die erste gesammelte Abschrift des Korans wurde bei ihr aufbewahrt."),
"sira_090": ("Welcher Gefährte überlieferte die meisten Hadithe des Propheten ﷺ?", ["Abu Hurayra", "Anas ibn Malik", "Abdullah ibn Umar", "Jabir"], "Abu Hurayra, der dem Propheten ﷺ eng verbunden war, ist der Gefährte mit den meisten überlieferten Hadithen."),
"sira_091": ("Welcher junge Gefährte diente dem Propheten ﷺ zehn Jahre lang, ohne je einen Tadel zu hören?", ["Anas ibn Malik", "Usama ibn Zayd", "Ibn Abbas", "Zayd ibn Thabit"], "Anas sagte: „Ich diente dem Propheten ﷺ zehn Jahre; nie sagte er ‚uff‘ zu mir, noch ‚warum hast du das getan?‘“"),
"sira_092": ("Für welchen jungen Cousin betete der Prophet ﷺ: „O Allah, lehre ihn das Buch“?", ["Abdullah ibn Abbas", "Ali", "Ja'far", "Usama"], "Der Prophet ﷺ umarmte Ibn Abbas und sagte: „O Allah, lehre ihn das Buch.“"),
"sira_093": ("Welchen Gefährten sandte der Prophet ﷺ in den Jemen mit der Weisung, zuerst zur Einheit Allahs aufzurufen?", ["Mu'adh ibn Jabal", "Bilal", "Abu Musa allein", "Zayd ibn Haritha"], "„Du kommst zu einem Volk der Schrift: Rufe sie zuerst dazu auf zu bezeugen, dass es keinen Gott außer Allah gibt…“"),
"sira_094": ("Welchen Gefährten nannte der Prophet ﷺ „den Vertrauenswürdigen (Amin) dieser Gemeinschaft“?", ["Abu Ubayda ibn al-Jarrah", "Abu Bakr", "Uthman", "Khalid"], "„Jede Gemeinschaft hat einen Vertrauenswürdigen, und der Vertrauenswürdige dieser Gemeinschaft ist Abu Ubayda ibn al-Jarrah.“"),
"sira_095": ("Welcher Gefährte, ein Schreiber der Offenbarung, wurde von Abu Bakr mit der Sammlung des Korans beauftragt?", ["Zayd ibn Thabit", "Abu Hurayra", "Anas ibn Malik", "Salman"], "Nach der Schlacht von al-Yamama beauftragte Abu Bakr Zayd ibn Thabit mit der Sammlung des Korans."),
"sira_096": ("Unter welchem Kalifen wurden offizielle Abschriften des Korans in die Provinzen gesandt?", ["Uthman ibn Affan", "Abu Bakr", "Umar", "Ali"], "Uthman ließ den Mushaf abschreiben und sandte ein Exemplar in jede Provinz."),
"sira_097": ("Aus welchem Land kam der Gefährte Salman, genannt „al-Farisi“?", ["Persien", "Abessinien", "Byzanz", "Jemen"], "Salman al-Farisi, „der Perser“, kam auf der Suche nach der Wahrheit aus Persien."),
"sira_098": ("Welcher aus dem byzantinischen Reich stammende Gefährte wird „ar-Rumi“ genannt?", ["Suhayb", "Bilal", "Salman", "Abu Dharr"], "Suhayb ar-Rumi wuchs unter den Byzantinern auf, bevor er in Mekka den Islam annahm."),
"sira_099": ("Wie heißt die Moschee des Propheten ﷺ in Medina?", ["Al-Masjid an-Nabawi", "Al-Masjid al-Haram", "Al-Masjid al-Aqsa", "Masjid Quba"], "Die Moschee, die er in Medina gründete, heißt Prophetenmoschee, al-Masjid an-Nabawi."),
"sira_100": ("Wie oft kommt der Name „Muhammad“ im Koran vor?", ["Viermal", "Einmal", "Zwölfmal", "Hundertmal"], "In den Versen 3:144, 33:40, 47:2 und 48:29; der Name „Ahmad“ erscheint in 61:6."),
"sira_101": ("Wie beschreibt der Koran den Propheten ﷺ für die Gläubigen in Vers 33:21?", ["Als schönes Vorbild", "Als strengen Richter", "Als König", "Als Dichter"], "„Ihr habt im Gesandten Allahs ein schönes Vorbild.“"),
"sira_102": ("Wie lautete die Kunya (der Vaternamen-Beiname) des Propheten ﷺ?", ["Abu al-Qasim", "Abu Bakr", "Abu Abdullah", "Abu Talib"], "Man nannte ihn Abu al-Qasim, nach seinem ältesten Sohn Al-Qasim."),
"sira_103": ("Wie hieß der in Medina geborene Sohn des Propheten ﷺ, der als kleines Kind starb?", ["Ibrahim", "Al-Qasim", "Abdullah", "Al-Hasan"], "Ibrahim, in Medina geboren, starb als Säugling; der Prophet ﷺ weinte und sagte, das Herz trauere, ohne zu sagen, was Allah missfällt."),
"sira_104": ("Für wen führte der Prophet ﷺ vor der Offenbarung eine Handelskarawane nach Syrien?", ["Khadija", "Abu Bakr", "Abu Sufyan", "Al-Abbas"], "Khadija, eine wohlhabende Kauffrau, vertraute ihm ihre Karawane nach Syrien an und machte ihm dann einen Heiratsantrag."),
"sira_105": ("Wie löste der junge Muhammad ﷺ den Streit der Sippen um das Wiedereinsetzen des Schwarzen Steins?", ["Er legte ihn auf ein Tuch, das jede Sippe anhob, und setzte ihn dann selbst ein", "Er trug ihn allein", "Er loste", "Er vertraute ihn Abu Bakr an"], "Er breitete einen Mantel aus, legte den Stein darauf, ließ die Sippenoberhäupter das Tuch gemeinsam anheben und setzte ihn eigenhändig ein."),
"sira_106": ("In welchem Alter empfing der Prophet ﷺ die erste Offenbarung?", ["Mit vierzig Jahren", "Mit fünfundzwanzig", "Mit fünfzig", "Mit sechzig"], "Die Offenbarung begann, als er vierzig Jahre alt war, in der Höhle Hira."),
"sira_107": ("Zu welchem schriftkundigen Cousin Khadijas wurde der Prophet ﷺ nach der ersten Offenbarung gebracht?", ["Waraqa ibn Nawfal", "Abu Talib", "Abu Lahab", "Al-Walid"], "Waraqa sagte: „Das ist der Namus (der Engel), den Allah zu Musa sandte.“"),
"sira_108": ("Auf welchen Hügel stieg der Prophet ﷺ, um die Quraysh öffentlich zu rufen, nach dem Vers „Warne deine nächsten Verwandten“?", ["As-Safa", "Uhud", "Arafat", "Hira"], "Er stieg auf as-Safa, rief die Sippen der Quraysh und warnte sie vor einer schweren Strafe."),
"sira_109": ("Welcher Kalif führte den muslimischen Kalender ein, der mit dem Jahr der Hidschra beginnt?", ["Umar ibn al-Khattab", "Abu Bakr", "Uthman", "Ali"], "Unter Umar wurde die Hidschra als Ausgangspunkt des Kalenders gewählt."),
"sira_110": ("Wie viele Jahre lebte der Prophet ﷺ nach der Hidschra in Medina?", ["Zehn", "Drei", "Zwanzig", "Dreizehn"], "Er lebte zehn Jahre in Medina, von der Hidschra bis zu seinem Tod im Jahr 11 n. H."),
"sira_111": ("Wie viele Jahre predigte der Prophet ﷺ vor der Hidschra in Mekka?", ["Dreizehn", "Drei", "Zehn", "Dreiundzwanzig"], "Dreizehn Jahre in Mekka, dann zehn in Medina: dreiundzwanzig Jahre der Sendung."),
"sira_112": ("Welcher Gefährte und Dichter verteidigte den Propheten ﷺ mit seinen Versen, und für wen erbat er Jibrils Beistand?", ["Hassan ibn Thabit", "Ka'b ibn Malik", "Abdullah ibn Rawaha", "Labid"], "Der Prophet ﷺ sagte zu Hassan: „Antworte ihnen, und Jibril ist mit dir.“"),
"sira_113": ("Von welchem Gefährten sagte der Prophet ﷺ, ihm sei für seine schöne Rezitation „eine der Flöten der Familie Dawuds“ gegeben worden?", ["Abu Musa al-Ash'ari", "Bilal", "Ubayy ibn Ka'b", "Ibn Mas'ud"], "Als er ihn rezitieren hörte, sagte der Prophet ﷺ, Abu Musa sei eine der Flöten der Familie Dawuds gegeben worden."),
"sira_114": ("Der Prophet ﷺ empfahl, den Koran von vier Gefährten zu lernen. Wer von diesen gehörte dazu?", ["Abdullah ibn Mas'ud", "Abu Hurayra", "Anas ibn Malik", "Khalid ibn al-Walid"], "„Lernt den Koran von vieren: Ibn Mas'ud, Salim, Mu'adh ibn Jabal und Ubayy ibn Ka'b.“"),
"sira_115": ("In welcher Schlacht wurde der Prophet ﷺ im Gesicht verletzt und verlor einen Zahn?", ["Uhud", "Badr", "Hunayn", "Khaybar"], "Bei Uhud brach sein Zahn, und sein Gesicht wurde verletzt."),
"sira_116": ("Zu welchem Gefährten, einem Bogenschützen bei Uhud, sagte der Prophet ﷺ: „Schieß! Mein Vater und meine Mutter seien dein Lösegeld“?", ["Sa'd ibn Abi Waqqas", "Talha", "Az-Zubayr", "Ali"], "Der Prophet ﷺ reichte ihm Pfeile und sagte: „Schieß, mein Vater und meine Mutter seien für dich geopfert.“"),
"sira_117": ("Welche Karawane zogen die Muslime abzufangen aus, was zur Schlacht von Badr führte?", ["Die Abu Sufyans, auf der Rückkehr aus Syrien", "Die des Negus", "Die der Perser", "Die von Ta'if"], "Die von Abu Sufyan geführte Karawane der Quraysh entkam, doch das mekkanische Heer kam nach Badr."),
"sira_118": ("Wann nahm der mekkanische Anführer Abu Sufyan den Islam an?", ["Bei der Eroberung Mekkas", "Vor der Hidschra", "Bei Badr", "Nach dem Tod des Propheten ﷺ"], "Abu Sufyan bekehrte sich am Vorabend des Einzugs des Propheten ﷺ in Mekka."),
"sira_119": ("Welche Quelle sprudelte für Hajar und ihren Sohn Isma'il im Tal von Mekka hervor?", ["Zamzam", "Der Nil", "Der Euphrat", "Der Jordan"], "Ein Engel schlug auf den Boden, und das Wasser von Zamzam sprudelte hervor; Hajar legte ein Becken darum an."),
"sira_120": ("Was war in den Ring des Propheten ﷺ eingraviert?", ["„Muhammad Rasul Allah“", "„Allahu Akbar“", "„La ilaha illa Allah“", "Nur sein Name"], "Sein silberner Ring trug „Muhammad, Gesandter Allahs“ in drei Zeilen."),
"sira_121": ("Welche Speisen mochte der Prophet ﷺ laut Aisha?", ["Süßes und Honig", "Fisch", "Scharfe Gewürze", "Nur Essig"], "Aisha berichtet, dass der Prophet ﷺ Süßes und Honig liebte."),
"sira_122": ("An welchem Wochentag wurde der Prophet ﷺ geboren, an dem er auch fastete?", ["Montag", "Freitag", "Samstag", "Mittwoch"], "Zum Fasten am Montag befragt, sagte er: „Das ist der Tag, an dem ich geboren wurde und an dem mir die Offenbarung kam.“"),
"sira_123": ("Wo befand sich das „Siegel des Prophetentums“ am Körper des Propheten ﷺ?", ["Zwischen seinen Schultern", "An seiner Hand", "Auf seiner Stirn", "Auf seiner Brust"], "Das Siegel des Prophetentums befand sich zwischen seinen Schultern."),
"sira_124": ("Aus welchem Holz fertigte ein Zimmermann den Minbar (die Kanzel) des Propheten ﷺ?", ["Tamariske (Athl)", "Zeder", "Olivenholz", "Palme"], "Der Prophet ﷺ ließ einen Minbar aus Tamariskenholz anfertigen, von dem aus er zu den Menschen sprach."),
"sira_125": ("Welche zwei großen Stämme Medinas bildeten die Ansar?", ["Die Aws und die Khazraj", "Quraysh und Thaqif", "Tamim und Hawazin", "Kinda und Hamdan"], "Die Aws und die Khazraj, lange Rivalen, vereinten sich im Islam und wurden zu den Ansar."),
"sira_126": ("Welchen Titel gibt der Koran den Ehefrauen des Propheten ﷺ?", ["Die Mütter der Gläubigen", "Die Königinnen von Medina", "Die Töchter der Quraysh", "Die Hüterinnen des Buches"], "„Seine Frauen sind ihre Mütter“: die Mütter der Gläubigen."),
"sira_127": ("In welchem Jahr des christlichen Kalenders fand die Hidschra statt?", ["622", "570", "632", "610"], "Die Hidschra im Jahr 622 markiert den Beginn des muslimischen Kalenders."),
"sira_128": ("Was antwortete Abd ar-Rahman ibn Awf, als sein Ansari-Bruder ihm die Hälfte seines Vermögens anbot?", ["„Zeig mir den Markt“", "Er nahm alles an", "Er bat um ein Haus", "Er verweigerte das Gespräch"], "Er sagte: „Möge Allah dein Vermögen und deine Familie segnen; zeig mir nur den Markt“, und er gedieh im Handel."),
"sira_129": ("Welchen Gefährten fragte der Prophet ﷺ, welcher Vers des Korans der größte sei, bevor er ihn zu seiner Antwort (dem Thronvers) beglückwünschte?", ["Ubayy ibn Ka'b", "Abu Bakr", "Zayd ibn Thabit", "Bilal"], "Ubayy antwortete: „Allah, es gibt keinen Gott außer Ihm, dem Lebendigen…“; der Prophet ﷺ sagte: „Möge das Wissen dich erfreuen, Abu al-Mundhir!“"),
"sira_130": ("Wie wurde der Standort der Moschee des Propheten ﷺ in Medina gewählt?", ["Dort, wo seine Kamelstute niederkniete", "Durch Los", "In der Mitte des Marktes", "Auf dem Berg Uhud"], "Er ließ seine Kamelstute frei laufen: Wo sie niederkniete, wurde die Moschee gebaut."),
"sira_131": ("Wie viele Söhne hatte der Prophet ﷺ, die alle jung starben?", ["Drei", "Einen", "Fünf", "Keinen"], "Al-Qasim und Abdullah, von Khadija geboren, und Ibrahim, in Medina geboren."),
"sira_132": ("Welcher Gefährte, vom Propheten ﷺ freigelassen und wie ein Sohn aufgezogen, war der Vater Usamas?", ["Zayd ibn Haritha", "Bilal", "Salman", "Ammar"], "Zayd ibn Haritha, vom Propheten ﷺ geliebt, war der Vater von Usama ibn Zayd."),
"sira_133": ("Welchen jungen Gefährten ernannte der Prophet ﷺ kurz vor seinem Tod trotz seiner Jugend zum Heerführer?", ["Usama ibn Zayd", "Anas ibn Malik", "Ibn Abbas", "Ibn Umar"], "Der Prophet ﷺ gab Usama den Befehl und antwortete denen, die sein Alter kritisierten, dass er dessen würdig sei, wie sein Vater."),
"sira_134": ("Welcher Großvater des Propheten ﷺ grub den seit langem verschütteten Brunnen Zamzam wieder aus?", ["Abd al-Muttalib", "Hashim", "Abd Manaf", "Qusayy"], "Abd al-Muttalib grub Zamzam wieder aus und betreute ihn für die Pilger."),
"sira_135": ("Wie viele Menschen begleiteten den Propheten ﷺ ungefähr in der Schlacht von Badr?", ["Etwas über dreihundert", "Zehntausend", "Tausend", "Fünfzig"], "Die Muslime bei Badr waren etwas über dreihundert, gegenüber einem weit größeren Heer."),
"sira_136": ("In welchem Monat des muslimischen Kalenders wurde der Prophet ﷺ geboren?", ["Rabi' al-Awwal", "Ramadan", "Muharram", "Dhul-Hijja"], "Er wurde im Monat Rabi' al-Awwal geboren, im Jahr des Elefanten."),
"sira_137": ("In welchem Monat kam der Prophet ﷺ während der Hidschra in Medina an?", ["Rabi' al-Awwal", "Ramadan", "Muharram", "Rajab"], "Er kam im Rabi' al-Awwal in Medina an, nach einem Aufenthalt in Quba."),
"sira_138": ("Welchen Pakt schlossen die Quraysh, um die Banu Hashim zu isolieren, die den Propheten ﷺ beschützten?", ["Einen Boykott: kein Handel und keine Heirat mit ihnen", "Einen zehnjährigen Waffenstillstand", "Eine Teilung der Ka'ba", "Ein Militärbündnis"], "Die Quraysh unterzeichneten einen Boykottpakt, und die Banu Hashim waren jahrelang in einem Tal eingeschlossen."),
"sira_139": ("Wie begann der Prophet ﷺ seine Sendung in Mekka, vor dem öffentlichen Ruf?", ["Indem er seinen engsten Kreis im Stillen rief", "Mit einem Heer", "Mit einem Brief an die Könige", "Mit einer Pilgerfahrt"], "Er rief zunächst seine Verwandten und Freunde im Privaten, bevor der Ruf öffentlich wurde."),
"sira_140": ("Zwischen welchen zwei Hügeln lief Hajar auf der Suche nach Wasser für Isma'il?", ["As-Safa und Al-Marwa", "Uhud und Thawr", "Arafat und Mina", "Hira und Thawr"], "Sie lief siebenmal zwischen as-Safa und al-Marwa: der Ursprung des Sa'y der Pilger."),
"sira_141": ("Von welchem Enkel sagte der Prophet ﷺ: „Dieser mein Sohn ist ein Sayyid; Allah wird durch ihn zwei Gruppen von Muslimen versöhnen“?", ["Al-Hasan", "Al-Husayn", "Usama", "Ibn Abbas"], "Al-Hasan ibn Ali versöhnte später zwei große Gruppen von Muslimen, wie der Prophet ﷺ vorausgesagt hatte."),
"sira_142": ("Wie hieß die Tochter des Propheten ﷺ, Mutter von Al-Hasan und Al-Husayn?", ["Fatima", "Zaynab", "Ruqayya", "Umm Kulthum"], "Fatima, Ehefrau Alis, war die Mutter von Al-Hasan und Al-Husayn."),
"sira_143": ("Wer war die älteste Tochter des Propheten ﷺ?", ["Zaynab", "Fatima", "Ruqayya", "Umm Kulthum"], "Zaynab war die älteste der vier Töchter des Propheten ﷺ."),
"sira_144": ("Welcher Gefährte, ein ehemaliger Sklave abessinischer Herkunft, wurde wegen seiner schönen Stimme zum Muezzin gewählt?", ["Bilal ibn Rabah", "Salman", "Suhayb", "Zayd"], "Bilal, von Abu Bakr freigekauft, wurde der Muezzin des Propheten ﷺ."),
"sira_145": ("Von welchem Gefährten sagte der Prophet ﷺ: „Wenn ich mir unter den Menschen einen engsten Freund (Khalil) nähme, wäre er es“?", ["Abu Bakr", "Umar", "Ali", "Uthman"], "„Wenn ich mir aus meiner Gemeinschaft einen engsten Freund nähme, nähme ich Abu Bakr, doch er ist mein Bruder und Gefährte.“"),
"sira_146": ("Welche Stadt wird zusammen mit Mekka „al-Haramayn“, die beiden Heiligtümer, genannt?", ["Medina", "Jerusalem", "Ta'if", "Damaskus"], "Mekka und Medina sind die beiden heiligen Städte, al-Haramayn."),
"sira_147": ("Wie oft vollzog der Prophet ﷺ nach der Hidschra den Hadsch?", ["Einmal, die Abschiedspilgerfahrt", "Dreimal", "Jedes Jahr", "Nie"], "Er vollzog nach der Hidschra nur einen Hadsch: die Abschiedspilgerfahrt im Jahr 10 n. H."),
"sira_148": ("Was tat der Prophet ﷺ laut Anas, als ein Beduine heftig an seinem Mantel zog und Güter forderte?", ["Er lächelte und befahl, ihm etwas zu geben", "Er ließ ihn bestrafen", "Er ging wortlos fort", "Er jagte ihn davon"], "Der Prophet ﷺ wandte sich ihm zu, lachte und befahl, ihm etwas zu geben."),
"sira_149": ("Welche Stadt, in der die al-Aqsa-Moschee steht, war das Ziel der Nachtreise?", ["Jerusalem", "Damaskus", "Kairo", "Bagdad"], "Die Nachtreise führte den Propheten ﷺ von Mekka zur al-Aqsa-Moschee in Jerusalem."),
"sira_150": ("Wie alt war der Prophet ﷺ, als er starb?", ["Dreiundsechzig", "Vierzig", "Fünfzig", "Achtzig"], "Er starb im Alter von dreiundsechzig Jahren, im Jahr 11 n. H."),
}
